15	
16	interface Props {
17	  mode: AlgorithmMode;
18	  tier: TierCopy;
19	  style: ModeStyle;
20	  isSelected: boolean;
21	  onSelect: (mode: AlgorithmMode) => void;
22	  scale?: number;
23	}
24	
25	export function TierPickerTile({ mode, tier, style, isSelected, onSelect, scale = 1 }: Props) {
26	  const { colors } = useThemeColors();
27	  const reduceMotion = useReduceMotion();
28	  const pressScale = useSharedValue(1);
29	  const animatedStyle = useAnimatedStyle(() => ({ transform: [{ scale: pressScale.value }] }));
30	  const checkSize = 24 * scale;
31	
32	  return (
33	    <Pressable
34	      accessibilityLabel={tier.tierName}
35	      accessibilityRole='radio'
36	      accessibilityState={{ selected: isSelected }}
37	      style={{ width: '100%' }}
38	      onPress={() => {
39	        if (!isSelected) void Haptics.selectionAsync();
40	        onSelect(mode);
41	      }}
42	      onPressIn={() => {
43	        if (!reduceMotion) pressScale.value = withSpring(0.96, { damping: 14, stiffness: 360 });
44	      }}
45	      onPressOut={() => {
46	        if (!reduceMotion) pressScale.value = withSpring(1, { damping: 14, stiffness: 360 });
47	      }}
48	    >
49	      <Animated.View
50	        className='items-center rounded-2xl'
