/** Per-mode visual palette for the Strength Curve picker. */
import { Mountain, Sprout, TrendingUp } from 'lucide-react-native';
import type { LucideIcon } from 'lucide-react-native';
import { colors } from '@/theme/colors';
import type { AlgorithmMode } from '@/components/AlgorithmPicker';

export interface ModeStyle {
  curveColor: string;
  curveTint: string;
  iconColor: string;
  iconTileBackground: string;
  tierPillBg: string;
  tierPillFg: string;
  Icon: LucideIcon;
}

export const MODE_STYLES: Record<AlgorithmMode, ModeStyle> = {
  forgiving: {
    curveColor: '#D97A3A',
    curveTint: 'rgba(217,122,58,0.12)',
    iconColor: colors.tone.orange.text,
    iconTileBackground: colors.tone.orange.bg,
    tierPillBg: colors.tone.orange.bg,
    tierPillFg: colors.tone.orange.text,
    Icon: Sprout,
  },
  balanced: {
    curveColor: colors.primary[700],
    curveTint: 'rgba(15,138,106,0.10)',
    iconColor: colors.primary[700],
    iconTileBackground: colors.primary[100],
    tierPillBg: colors.primary[100],
    tierPillFg: '#086148',
    Icon: TrendingUp,
  },
  strict: {
    curveColor: colors.premium[500],
    curveTint: 'rgba(133,99,199,0.12)',
    iconColor: colors.premium[600],
    iconTileBackground: '#EEE7FA',
    tierPillBg: '#EEE7FA',
    tierPillFg: '#3F2F75',
    Icon: Mountain,
  },
};

/** Copy for the Strength Curve full-screen picker (V5 + Option B). */
import type { AlgorithmMode } from '@/components/AlgorithmPicker';

export const STRENGTH_CURVE_PICKER_COPY = {
  headerTitle: 'Habit strength',
  doneLabel: 'Done',
  heroTitle: 'Strength fills like this.',
  heroSubtitle: 'Check in to grow it. Miss a day and it dips.',
  pickerSectionLabel: 'What kind of habit is this?',
  freshStartLabel: 'Fresh start',
  automaticLabel: 'Automatic',
  checkInLabel: 'Check in',
  missLabel: 'Skip a day',
} as const;

export interface TierCopy {
  emoji: string;
  tierName: string;
  durationPerDay: string;
  formationWeeks: string;
  formationDays: string;
  examples: string;
  midpointLabel: string;
  midpointSub: string;
  automaticMilestone: string;
  fillPercent: string;
  dipPercent: string;
  detailHeading: string;
  description: string;
  exampleChips: readonly string[];
}

export const TIER_COPY: Record<AlgorithmMode, TierCopy> = {
  forgiving: {
    emoji: '⚡',
