/** MechanicStatRow — two-card check-in / miss explainer with per-tier numbers + stagger. */
import { Text, View } from 'react-native';
import Animated, { FadeInDown } from 'react-native-reanimated';
import type { AlgorithmMode } from '@/components/AlgorithmPicker';
import { useReduceMotion } from '@/hooks/useReduceMotion';
import { useThemeColors } from '@/theme/ThemeContext';
import { STRENGTH_CURVE_PICKER_COPY, TIER_COPY } from './StrengthCurvePicker.copy';
import { MODE_STYLES } from './strengthCurveModeStyles';

const MISS_COLOR = '#C84A4A';

export function MechanicStatRow({ mode, scale = 1 }: { mode: AlgorithmMode; scale?: number }) {
  const { colors } = useThemeColors();
  const reduceMotion = useReduceMotion();
  const tier = TIER_COPY[mode];
  const accent = MODE_STYLES[mode].curveColor;
  const gain = reduceMotion ? undefined : FadeInDown.delay(80).duration(280);
  const dip = reduceMotion ? undefined : FadeInDown.delay(160).duration(280);

  const cardStyle = {
    backgroundColor: colors.card,
    borderColor: colors.border,
    borderWidth: 1,
    borderLeftWidth: 4,
    padding: 12 * scale,
  } as const;

  return (
    <View className='flex-row mx-4' style={{ gap: 10 * scale, marginTop: 12 * scale }}>
      <Animated.View
        key={`gain-${mode}`}
        entering={gain}
        className='flex-1 items-center rounded-2xl'
        style={{ ...cardStyle, borderLeftColor: accent }}
      >
        <Text style={{ color: accent, fontSize: 24 * scale, lineHeight: 26 * scale }}>✓</Text>
        <Text className='font-bold' style={{ color: colors.text.primary, fontSize: 12 * scale, marginTop: 2 * scale }}>
          {STRENGTH_CURVE_PICKER_COPY.checkInLabel}
        </Text>
        <Text className='font-extrabold' style={{ color: accent, fontSize: 22 * scale, marginTop: 2 * scale }}>
          {tier.fillPercent}
        </Text>
      </Animated.View>
      <Animated.View
        key={`dip-${mode}`}
        entering={dip}
        className='flex-1 items-center rounded-2xl'
        style={{ ...cardStyle, borderLeftColor: MISS_COLOR }}
      >
        <Text style={{ color: MISS_COLOR, fontSize: 24 * scale, lineHeight: 26 * scale }}>✗</Text>
        <Text className='font-bold' style={{ color: colors.text.primary, fontSize: 12 * scale, marginTop: 2 * scale }}>
          {STRENGTH_CURVE_PICKER_COPY.missLabel}
        </Text>
        <Text className='font-extrabold' style={{ color: MISS_COLOR, fontSize: 22 * scale, marginTop: 2 * scale }}>
          {tier.dipPercent}
        </Text>
      </Animated.View>
    </View>
  );
}

/** StrengthCurvePickerModal — full-screen picker (V5 Giant Bar Hero). */
import { Text, useWindowDimensions, View } from 'react-native';
import Animated, { FadeInDown } from 'react-native-reanimated';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import Modal from '@/components/Modal';
import type { AlgorithmMode } from '@/components/AlgorithmPicker';
import { useReduceMotion } from '@/hooks/useReduceMotion';
import { useThemeColors } from '@/theme/ThemeContext';
import { MechanicStatRow } from './MechanicStatRow';
import { STRENGTH_CURVE_PICKER_COPY } from './StrengthCurvePicker.copy';
import { StrengthBarHero } from './StrengthBarHero';
import { StrengthCurvePickerHeader } from './StrengthCurvePickerHeader';
import { TierDetailCard } from './TierDetailCard';
import { TierPickerRow } from './TierPickerRow';

const SCALE_BASE = 600;
const SCALE_MAX = 850;
const SCALE_RANGE = 0.30;

function computeScale(usableHeight: number): number {
  const t = Math.max(0, Math.min(1, (usableHeight - SCALE_BASE) / (SCALE_MAX - SCALE_BASE)));
  return 1 + t * SCALE_RANGE;
}

interface Props {
  visible: boolean;
  selected: AlgorithmMode;
  onSelect: (mode: AlgorithmMode) => void;
  onClose: () => void;
}

export function StrengthCurvePickerModal({ visible, selected, onSelect, onClose }: Props) {
  const insets = useSafeAreaInsets();
  const { colors } = useThemeColors();
  const reduceMotion = useReduceMotion();
  const { height: windowHeight } = useWindowDimensions();
  const scale = computeScale(windowHeight - insets.top - insets.bottom - 56);

  return (
    <Modal variant='fullScreen' visible={visible} onClose={onClose}>
      <View className='flex-1' style={{ backgroundColor: colors.background }}>
        <StrengthCurvePickerHeader topInset={insets.top} onClose={onClose} />
        <Animated.View
          className='items-center'
          entering={reduceMotion ? undefined : FadeInDown.duration(280)}
          style={{ paddingHorizontal: 20, paddingTop: 12 * scale, paddingBottom: 4 * scale }}
        >
          <Text
            className='text-center font-extrabold leading-tight'
            style={{ color: colors.text.primary, fontSize: 24 * scale }}
          >
            {STRENGTH_CURVE_PICKER_COPY.heroTitle}
          </Text>
          <Text
            className='text-center'
            style={{ color: colors.text.secondary, fontSize: 13 * scale, marginTop: 4 * scale }}
          >
            {STRENGTH_CURVE_PICKER_COPY.heroSubtitle}
          </Text>
        </Animated.View>
        <StrengthBarHero mode={selected} scale={scale} />
        <MechanicStatRow mode={selected} scale={scale} />
        <Animated.Text
          className='text-center font-bold tracking-wider'
          entering={reduceMotion ? undefined : FadeInDown.delay(180).duration(260)}
          style={{
            color: colors.text.tertiary,
            fontSize: 10.5 * scale,
            marginTop: 14 * scale,
            marginBottom: 8 * scale,
          }}
        >
          {STRENGTH_CURVE_PICKER_COPY.pickerSectionLabel.toUpperCase()}
        </Animated.Text>
        <TierPickerRow scale={scale} selected={selected} onSelect={onSelect} />
        <View style={{ marginBottom: insets.bottom + 16 }}>
          <TierDetailCard mode={selected} scale={scale} />
        </View>
      </View>
    </Modal>
  );
}

